/**
 * 生成36进制表示的uuid，
 * @param {Number} length 保留长度
 * @return {*}
 */
export function uuid(length) {
  if (length === void 0) {
    length = 6;
  }
  return ''.padEnd(length, Math.random().toString(36).substring(3));
}
export function mockId() {
  return "id-" + uuid();
}